func:
// Validation et mise en forme
let speed = msg.payload;

// Validation de la plage
if (speed < 0 || speed > 3000) {
    node.warn("Motor speed out of range: " + speed);
    return null;
}

// Calcul du pourcentage (nominal = 1500 RPM)
let speedPercent = (speed / 1500) * 100;

// Détection d'anomalie
let anomaly = false;
if (speed < 500 || speed > 2500) {
    anomaly = true;
}

msg.payload = {
    measurement: "motor",
    fields: {
        speed: speed,
        speed_percent: speedPercent,
        anomaly: anomaly ? 1 : 0
    },
    tags: {
        location: "line1",
        sensor: "speed_sensor"
    },
    timestamp: new Date().getTime() * 1000000
};

return msg;

// Validation et alarmes
let temp = msg.payload;

// Seuils d'alarme
let warning = temp > 75;
let critical = temp > 85;

msg.payload = {
    measurement: "temperature",
    fields: {
        value: temp,
        warning: warning ? 1 : 0,
        critical: critical ? 1 : 0
    },
    tags: {
        location: "line1",
        sensor: "temp_sensor"
    },
    timestamp: new Date().getTime() * 1000000
};

if (critical) {
    node.warn("CRITICAL: Temperature = " + temp + "°C");
}

return msg;

// Lissage avec moyenne mobile (contexte)
let pressure = msg.payload;

// Récupération de l'historique
let history = context.get('pressure_history') || [];
history.push(pressure);

// Garde uniquement les 5 dernières valeurs
if (history.length > 5) {
    history.shift();
}
context.set('pressure_history', history);

// Calcul de la moyenne
let avg = history.reduce((a, b) => a + b, 0) / history.length;

msg.payload = {
    measurement: "pressure",
    fields: {
        value: pressure,
        average: avg,
        deviation: Math.abs(pressure - avg)
    },
    tags: {
        location: "line1",
        sensor: "pressure_sensor"
    },
    timestamp: new Date().getTime() * 1000000
};

return msg;

// Filtrage et détection d'anomalies
let vibration = msg.payload;

// Seuils
let normal = vibration < 0.6;
let warning = vibration >= 0.6 && vibration < 0.8;
let critical = vibration >= 0.8;

let status = normal ? "Normal" : (warning ? "Warning" : "Critical");

msg.payload = {
    measurement: "vibration",
    fields: {
        value: vibration,
        status_code: normal ? 0 : (warning ? 1 : 2)
    },
    tags: {
        location: "line1",
        sensor: "vibration_sensor",
        status: status
    },
    timestamp: new Date().getTime() * 1000000
};

if (critical) {
    node.error("CRITICAL VIBRATION: " + vibration + " mm/s");
}

return msg;

// Calcul de puissance estimée
let current = msg.payload;
let voltage = 400; // V triphasé
let powerFactor = 0.85;

// P = √3 × V × I × cos(φ)
let power = Math.sqrt(3) * voltage * current * powerFactor / 1000; // kW

msg.payload = {
    measurement: "electrical",
    fields: {
        current: current,
        power_kw: power,
        voltage: voltage
    },
    tags: {
        location: "line1",
        phase: "3ph"
    },
    timestamp: new Date().getTime() * 1000000
};

return msg;

// Calcul du taux de production
let count = msg.payload;
let lastCount = context.get('last_production_count') || count;
let lastTime = context.get('last_production_time') || Date.now();

let currentTime = Date.now();
let deltaCount = count - lastCount;
let deltaTime = (currentTime - lastTime) / 1000; // secondes

// Taux par heure
let rate = deltaTime > 0 ? (deltaCount / deltaTime) * 3600 : 0;

context.set('last_production_count', count);
context.set('last_production_time', currentTime);

msg.payload = {
    measurement: "production",
    fields: {
        total_count: count,
        rate_per_hour: rate,
        delta_count: deltaCount
    },
    tags: {
        location: "line1",
        line: "production_line_1"
    },
    timestamp: new Date().getTime() * 1000000
};

return msg;

// Codage numérique des états
let state = msg.payload;
let stateCode = 0;

switch(state) {
    case "Stopped": stateCode = 0; break;
    case "Starting": stateCode = 1; break;
    case "Running": stateCode = 2; break;
    case "Alarm": stateCode = 3; break;
    default: stateCode = -1;
}

// Détection des changements d'état
let lastState = context.get('last_state') || state;
let stateChanged = (lastState !== state);

if (stateChanged) {
    node.warn("State changed: " + lastState + " -> " + state);
    context.set('last_state', state);
}

msg.payload = {
    measurement: "machine_state",
    fields: {
        state_code: stateCode,
        state_changed: stateChanged ? 1 : 0
    },
    tags: {
        location: "line1",
        state: state
    },
    timestamp: new Date().getTime() * 1000000
};

return msg;

// Indicateur de qualité avec statistiques
let quality = msg.payload;

// Historique pour moyenne glissante
let history = context.get('quality_history') || [];
history.push(quality);

if (history.length > 10) {
    history.shift();
}
context.set('quality_history', history);

let avg = history.reduce((a, b) => a + b, 0) / history.length;
let variance = history.reduce((sum, val) => sum + Math.pow(val - avg, 2), 0) / history.length;
let stdDev = Math.sqrt(variance);

msg.payload = {
    measurement: "quality",
    fields: {
        value: quality,
        average: avg,
        std_deviation: stdDev,
        below_target: quality < 95 ? 1 : 0
    },
    tags: {
        location: "line1",
        product: "product_a"
    },
    timestamp: new Date().getTime() * 1000000
};

return msg;
